@push('scripts')
<script>
document.addEventListener('DOMContentLoaded',function(){
    const form=document.getElementById('cash-payment-form');if(!form)return;
    const amount=document.getElementById('cash-payment-amount'),received=document.getElementById('cash-received'),output=document.getElementById('cash-change'),note=document.getElementById('cash-change-note'),submit=document.getElementById('cash-submit'),fee=document.getElementById('cash-fee'),student=document.getElementById('cash-student'),description=document.getElementById('cash-description');
    function updateFeeOptions(){[...fee.options].forEach(function(option){option.hidden=!!option.value&&option.dataset.studentId!==student.value;});if(fee.selectedOptions[0]&&fee.selectedOptions[0].hidden)fee.value='';}
    function applyFee(){const option=fee.selectedOptions[0];if(option&&option.value){student.value=option.dataset.studentId;amount.value=option.dataset.amount;description.value=option.dataset.title;}updateFeeOptions();update();}
    const rupiah=new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',minimumFractionDigits:0,maximumFractionDigits:2});
    function update(){
        const due=Number(amount.value),tender=Number(received.value),filled=amount.value!==''&&received.value!==''&&Number.isFinite(due)&&Number.isFinite(tender)&&due>=1000;
        received.min=due>=1000?String(due):'1000';received.setCustomValidity('');
        if(!filled){output.textContent=rupiah.format(0);note.textContent='Isi nominal pembayaran dan uang diterima untuk menghitung kembalian.';submit.disabled=true;return;}
        const change=Math.round(tender*100)-Math.round(due*100);
        if(change<0){output.textContent='Uang belum cukup';note.textContent='Uang diterima kurang '+rupiah.format(-change/100)+'.';received.setCustomValidity('Uang diterima tidak boleh kurang dari nominal pembayaran kas.');submit.disabled=true;return;}
        output.textContent=rupiah.format(change/100);note.textContent=change===0?'Uang pas, tidak ada kembalian.':'Kembalikan '+rupiah.format(change/100)+' kepada siswa. Yang masuk kas tetap '+rupiah.format(due)+'.';submit.disabled=false;
    }
    student.addEventListener('change',updateFeeOptions);fee.addEventListener('change',applyFee);amount.addEventListener('input',update);received.addEventListener('input',update);updateFeeOptions();applyFee();
});
</script>
